{"explanation":"Automatically apply square icon-button geometry to icon-only buttons with no child elements or only screen-reader text, and cover the generated CSS contract.","input":"*** Begin Patch
*** Update File: /Users/dwahl/Scripts/pantoken/formats/components/src/components/button/button.css
@@
-  &.-shape-square {
+  &.-shape-square,
+  &[class*="-icon-"]:not(:has(> *)),
+  &[class*="-icon-"]:has(> .instui-screen-reader-content:only-child) {
     padding: var(--instui-spacing-space-xs);
     aspect-ratio: 1;
   }
@@
   &.-shape-square[class*="-icon-"]::before,
   &.-shape-circle[class*="-icon-"]::before {
+  &.-shape-square[class*="-icon-"]::before,
+  &.-shape-circle[class*="-icon-"]::before,
+  &[class*="-icon-"]:not(:has(> *))::before,
+  &[class*="-icon-"]:has(> .instui-screen-reader-content:only-child)::before {
     inline-size: 1.25em;
     block-size: 1.25em;
     margin-inline-end: 0;
*** Update File: /Users/dwahl/Scripts/pantoken/formats/components/tests/components/button.test.ts
@@
 test("button icon modifiers center the glyph and add the expected gap", () => {
   const css = buttonCss({ prefix: "instui" });
   expect(css).toContain('&[class*="-icon-"]::before');
@@
   expect(css).toContain("block-size: 1em");
 });
+
+test("icon-only buttons automatically use square icon-button geometry", () => {
+  const css = buttonCss({ prefix: "instui" });
+  expect(css).toContain('&[class*="-icon-"]:not(:has(> *))');
+  expect(css).toContain('&[class*="-icon-"]:has(> .instui-screen-reader-content:only-child)');
+  expect(css).toContain("aspect-ratio: 1");
+  expect(css).toContain("inline-size: 1.25em");
+  expect(css).toContain("margin-inline-end: 0");
+});
*** End Patch"}

